mapper.update:
update oc_outbox_event
set consume_status = '5',
    consume_error = #{consumeError},
    completed_time = sysdate(),
    process_time_ms = case
        when consumed_time is null then null
        else greatest(
            timestampdiff(microsecond, consumed_time, sysdate()) div 1000, 0
        )
    end,
    update_time = sysdate()
where event_id = #{eventId}
  and consume_status in ('0', '1')
